'use strict';
const token=document.querySelector('meta[name="app-token"]').content;
const $=id=>document.getElementById(id);
let current=null, pending=false, uploading=false, busy=false, creating=false, selected=new Set(), lastMessages='', previewRequest=0, reviewTarget=null, driveConfigured=false;
const extractionViews=new Map();
const analysisViews=new Map();
const requirementDrafts=new Map();
function node(tag,text,className){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n;}
function error(e){$('error').hidden=!e;$('error').textContent=e?String(e.message||e):'';}
async function api(path,options={}){
  const headers={'X-Engineer-Token':token,...options.headers};
  if(options.body && typeof options.body==='object' && !(options.body instanceof ArrayBuffer)){options.body=JSON.stringify(options.body);headers['Content-Type']='application/json';}
  const response=await fetch(path,{...options,headers,cache:'no-store'});
  if(!response.ok){let message=`Ошибка ${response.status}`;try{message=(await response.json()).error||message;}catch{}throw new Error(message);}
  return response.headers.get('content-type').startsWith('application/json')?response.json():response;
}
function controls(){document.querySelectorAll('.extract-native,.extract-docling,.extract-ocr,.extract-resume,.analysis-resume').forEach(b=>b.disabled=busy||pending||uploading); $('drive-import').disabled=!driveConfigured||!current||pending||uploading||busy;$('drive-source').disabled=pending||uploading;$('drive-sha').disabled=pending||uploading;$('core-checks').hidden=$('task-mode').value==='CHAT';document.querySelectorAll('#core-checks input').forEach(c=>{c.disabled=pending||busy||uploading;});document.querySelectorAll('nav .session').forEach(button=>{button.disabled=pending||uploading;});$('send').disabled=!current||pending||busy||uploading;$('upload').disabled=!current||uploading||pending;$('new-chat').disabled=creating||pending||uploading;$('prompt').disabled=!current;$('task-mode').disabled=pending||busy||uploading;$('review-save').disabled=!reviewTarget||pending||uploading;document.querySelectorAll('.review-button').forEach(b=>b.disabled=pending||uploading);$('evidence-save').disabled=!current||pending||uploading||!$('evidence-file').options.length;$('tz-save').disabled=!current||pending||uploading;document.querySelectorAll('.requirement-save,.candidate-from-source').forEach(b=>b.disabled=pending||uploading); }
async function sessions(){const list=await api('/api/sessions');$('sessions').replaceChildren();for(const s of list){const b=node('button',s.title,s.id===current?'session active':'session');b.disabled=pending||uploading;b.onclick=()=>switchSession(s.id);$('sessions').append(b);}return list;}
async function switchSession(id,{internal=false}={}){if((pending&&!internal)||uploading)return;extractionViews.clear();analysisViews.clear();closePreview();closeReview();requirementDrafts.clear();resetDomains();resetCaseRoles();resetHistory();clearCandidateLocation();$('tz-text').value='';current=id;selected=new Set();lastMessages='';for(const field of ['evidence-quote','evidence-statement','evidence-page','drive-source','drive-sha'])$(field).value='';error(null);controls();await refresh();await sessions();}
async function createSession(){if(creating||pending||uploading)return;creating=true;controls();try{const s=await api('/api/sessions',{method:'POST',body:{title:'Новый диалог'}});await switchSession(s.id);}catch(e){error(e);}finally{creating=false;controls();}}
function renderMessages(snap){const key=JSON.stringify(snap.messages);if(key===lastMessages)return;lastMessages=key;$('messages').replaceChildren();if(!snap.messages.length){const e=node('div',undefined,'empty');e.append(node('span','E','empty-symbol'),node('h2','Начните с задачи'),node('p','Опишите вопрос или прикрепите ТЗ. История останется доступна после перезапуска.'));$('messages').append(e);}if(snap.history_windowed)$('messages').append(node('p','Показаны последние 200 сообщений. Полный архив доступен в разделе «История».','muted'));for(const m of snap.messages){const article=node('article',undefined,`message ${m.role}`);article.append(node('div',m.role==='user'?'ВЫ':'ENGINEER OS','label'),node('div',m.content,'message-body'));if(m.role==='assistant')article.append(node('small','Предварительный ответ · требуется проверка'));$('messages').append(article);} $('messages').scrollTop=$('messages').scrollHeight;}
async function download(f){try{const response=await api(`/api/files/${f.id}`);const url=URL.createObjectURL(await response.blob());const link=node('a');link.href=url;link.download=f.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}catch(e){error(e);}}
function renderCoverage(c){const box=node('details',undefined,'coverage');box.append(node('summary','Покрытие извлечения'));if(!c||c.status==='UNKNOWN'){box.append(node('p','Покрытие неизвестно: прежняя запись или извлечение недоступно.'));}else if(c.method==='NATIVE_PDF'){box.append(node('p',`Native-текст: попытка ${c.attempted_pages}/${c.total_pages} страниц; текст найден на ${c.pages_with_text}; не обработано ${c.unattempted_pages}.`));if(c.pages_without_text?.length)box.append(node('p','Без native-текста: страницы '+c.pages_without_text.join(', ')+'. Это не доказывает отсутствие содержания.'));for(const r of c.page_records||[])box.append(node('small',`Страница ${r.page}: ${r.status==='NO_NATIVE_TEXT'?'native-текст не найден':r.status==='PARTIAL_TEXT'?'текст усечён':'кандидат текста'} · сохранено ${r.stored_chars}/${r.text_chars} символов.`));}else{box.append(node('p',`UTF-8: сохранено ${c.stored_chars}/${c.source_chars} символов. Страницы неприменимы.`));}const reasons={PAGE_LIMIT:'Лимит 20 страниц',CHAR_LIMIT:'Лимит символов',EXTRACTION_UNAVAILABLE:'Извлечение недоступно',LEGACY_UNKNOWN:'Старое извлечение без покрытия'};for(const reason of c?.stop_reasons||[])box.append(node('small',reasons[reason]||reason));box.append(node('small','Полнота документа не проверена. Таблицы и графика не проверены; OCR не выполнен.'));return box;}
async function extractionAction(path,body){if(!current||busy||pending||uploading)return;pending=true;controls();error(null);try{await api(path,{method:'POST',body});await refresh();await sessions();}catch(e){error(e);}finally{pending=false;controls();}}
function extractionButtons(f){const box=node('details',undefined,'advanced-document-actions');box.append(node('summary','Дополнительные действия с документом'));for(const [backend,label] of (f.name.toLowerCase().endsWith('.pdf')?[['native','Все страницы · native без OCR'],['docling','Docling · OCR и таблицы'],['ocr','Локальный OCR · русский и английский']]:[['ocr','Локальный OCR · русский и английский']])){const button=node('button',label,'extract-'+backend+' text-button');button.disabled=busy||pending||uploading;button.onclick=()=>extractionAction(`/api/sessions/${current}/extraction`,{file_id:f.id,backend});box.append(button);}return box;}
async function extractionJournal(job,more=false,page=null){const session=current;try{let view=extractionViews.get(job.id)||{pages:[],has_more:false,text:null};if(page!==null){const r=await api(`/api/sessions/${session}/jobs/${job.id}/pages/${page}`);view.text={page,text:r.blocks.map(b=>b.text).join('\n')};}else{const r=await api(`/api/sessions/${session}/jobs/${job.id}/pages?offset=${more?view.pages.length:0}&limit=50`);view={pages:more?[...view.pages,...r.pages]:r.pages,has_more:r.has_more,text:view.text};}if(current!==session)return;extractionViews.set(job.id,view);await refresh();}catch(e){if(current===session)error(e);}}
function renderExtraction(card,job){const r=job.result?.extraction;const box=node('details',undefined,'extraction-run');box.append(node('summary','Извлечение документа · '+(r?.backend||job.mode)),node('small','UNVERIFIED · полнота не проверена · FINAL AUDIT NOT_RUN'));if(r)box.append(node('p',`Обработано ${r.processed_pages}/${r.total_pages} · BLOCK ${r.blocked_pages} · ошибки ${r.failed_pages}`),node('p','OCR: '+r.ocr+(r.current_page?' · текущая страница '+r.current_page:'')));const journal=node('button','Журнал страниц / обновить','extraction-journal text-button');journal.onclick=()=>extractionJournal(job);box.append(journal);const view=extractionViews.get(job.id);if(view){for(const p of view.pages){const row=node('div');row.append(node('small',`Страница ${p.page} · ${p.execution} · ${p.status} · ${p.stored_chars} символов`));for(const limit of p.limitations)row.append(node('small',limit));const text=node('button','Текст страницы '+p.page,'extraction-page text-button');text.onclick=()=>extractionJournal(job,false,p.page);row.append(text);box.append(row);}if(view.has_more){const more=node('button','Ещё 50 страниц','text-button');more.onclick=()=>extractionJournal(job,true);box.append(more);}if(view.text)box.append(node('pre','Страница '+view.text.page+' · непроверенный текст\n'+view.text.text,'extraction-text'));}if(r&&!r.budget_exhausted&&(['FAILED','CANCELLED'].includes(job.state)||r.failed_pages>0)&&job.state!=='RUNNING'&&job.state!=='QUEUED'){const button=node('button','Продолжить извлечение','extract-resume text-button');button.disabled=busy||pending||uploading;button.onclick=()=>extractionAction(`/api/sessions/${current}/jobs/${job.id}/resume`,{});box.append(button);}card.append(box);}
async function analysisDrafts(job,more=false){const session=current;try{const old=analysisViews.get(job.id)||[];const r=await api(`/api/sessions/${session}/jobs/${job.id}/analysis?offset=${more?old.length:0}&limit=50`);if(current!==session)return;analysisViews.set(job.id,more?[...old,...r.records]:r.records);await refresh();}catch(e){if(current===session)error(e);}}
function renderAnalysisResume(box,job,r){
 if(r.summary_input_clipped)box.append(node('small','При свёртке обрезано '+r.summary_omitted_chars+' символов черновиков. Полные черновики доступны в результатах по частям; сохранность деталей сводки не подтверждена.'));
 if(r.model_calls!==undefined)box.append(node('small','Вызовов модели: '+r.model_calls+' · время: '+Math.round(r.model_elapsed_seconds||0)+' с'+(r.model_elapsed_estimated?' (включает оценку прерванных вызовов)':'')+' · Повторно использовано: '+(r.calls_reused||0)));
 if(r.budget_exhausted)box.append(node('small','Бюджет анализа исчерпан; продолжение не сбрасывает лимиты.'));
 if(!r.resume_supported&&job.state==='FAILED')box.append(node('small','Идентичность модели не подтверждена; для повтора создайте новое задание.'));
 if(r.resume_supported&&!r.budget_exhausted&&(['FAILED','CANCELLED'].includes(job.state)||(job.state==='SUCCEEDED'&&!r.all_batches_completed))){
  const resume=node('button','Продолжить анализ','analysis-resume text-button');resume.disabled=busy||pending||uploading;
  resume.onclick=()=>extractionAction(`/api/sessions/${current}/jobs/${job.id}/resume-analysis`,{});box.append(resume);
 }
}
function sourceLocation(ref){
 const l=ref.locator;if(!l)return 'стр. '+ref.page;
 const derived=l.scope==='DERIVED_DOCX_LOCATION'?'DOC→DOCX (привязка производная) · ':'';
 return derived+(l.cell?l.sheet+'!'+l.cell:l.kind==='paragraph'?'абзац '+l.paragraph:l.kind==='table_cell'?'таблица '+l.table+', строка '+l.row+', ячейка '+l.column:'элемент '+ref.logical_unit);
}
function renderAutomaticAnalysis(card,job){const r=job.result.document_analysis;const box=node('div',undefined,'automatic-analysis');const labels={PREPARING:'Обрабатываем документ',ANALYZING:'Анализируем документ по частям',SUMMARIZING:'Собираем итоговую сводку',COMPLETED:'Анализ частей завершён',PARTIAL:'Сохранена часть анализа'};box.append(node('strong',labels[r.stage]||r.stage));for(const s of r.sources){box.append(node('p',s.name+' · обработано '+(s.processed_units??s.processed_pages??'—')+'/'+(s.total_units??s.total_pages??'—')+(s.total_units!==undefined?' логических элементов; физические страницы неизвестны':' страниц')));if(s.blocked_pages||s.failed_pages){box.append(node('small','Есть непрочитанные или ограниченные части: '+(s.blocked_pages||0)+'. '+(s.unavailable_pages?.length?(s.total_units!==undefined?'Элементы: ':'Страницы: ')+s.unavailable_pages.join(', '):'')));}if(s.coverage_manifest){const m=s.coverage_manifest;box.append(node('small','Покрытие логических элементов: '+m.processed_units+'/'+m.declared_units+'; остаток '+m.unprocessed_units));for(const sheet of m.sheets)box.append(node('small','Лист '+sheet.name+' · элементов '+sheet.units));for(const table of m.tables)box.append(node('small','Таблица '+table.table+' · ячеек '+table.cells));}for(const reason of s.limitations||[])box.append(node('small',reason));}if(r.batches_total)box.append(node('p','Части анализа: '+r.batches_completed+'/'+r.batches_total));if(r.text_omitted)box.append(node('small','Из-за лимита передана часть текста документа.'));if(r.summary_compressed)box.append(node('small','Итог — сводка черновиков; подробные результаты по частям сохранены.'));box.append(node('small','Содержание и полнота требуют проверки; инженерное принятие отсутствует.'));const button=node('button','Результаты по частям','analysis-drafts text-button');button.onclick=()=>analysisDrafts(job);box.append(button);const records=analysisViews.get(job.id);if(records){for(const item of records){const part=node('details',undefined,'analysis-receipt');part.append(node('summary',(item.kind==='SOURCE_PART'?'Часть документа':'Сводка')+' · '+item.status));if(item.refs?.length)part.append(node('small','Места источника: '+item.refs.map(sourceLocation).join(', ')));for(const ref of item.refs||[]){const bind=node('button','Создать кандидата · '+sourceLocation(ref),'candidate-from-source text-button');bind.onclick=()=>candidateFromSource(ref);part.append(bind);}part.append(node('pre',item.text||item.error,'extraction-text'));box.append(part);}if(records.length&&records.length%50===0){const more=node('button','Ещё результаты','text-button');more.onclick=()=>analysisDrafts(job,true);box.append(more);}}renderAnalysisResume(box,job,r);card.append(box);}
function renderFiles(files){$('files').replaceChildren();if(!files.length)$('files').append(node('p','Пока нет файлов','muted'));for(const f of files){const card=node('div',undefined,'file');const label=node('label');const check=node('input');check.type='checkbox';check.checked=selected.has(f.id);check.disabled=busy||pending;check.onchange=()=>check.checked?selected.add(f.id):selected.delete(f.id);label.append(check,node('span',f.name));const button=node('button','Скачать оригинал','text-button');button.onclick=()=>download(f);if(f.source_metadata?.provider==='GOOGLE_DRIVE')card.append(node('small','Drive · ID '+f.source_metadata.drive_file_id+' · SHA256 '+f.sha256));card.append(label,node('small',`${(f.size/1024/1024).toFixed(2)} МБ · ${f.extraction_status==='UNAVAILABLE'?'Текст недоступен':'Текст не проверен'}`),node('small',f.extraction_note),renderCoverage(f.extraction_coverage),button);if(/\.(pdf|docx|xlsx|doc|png|jpg|jpeg)$/i.test(f.name)){card.append(node('small','Документ обработается автоматически при отправке задачи.'));if(/\.(pdf|png|jpg|jpeg)$/i.test(f.name))card.append(extractionButtons(f));}if(/\.(pdf|png|jpg|jpeg)$/i.test(f.name)){const page=node('input');page.type='number';page.min='1';page.step='1';page.value='1';page.setAttribute('aria-label','Страница оригинала '+f.name);const preview=node('button','Просмотреть оригинал','text-button');preview.onclick=()=>showPreview({name:f.name,page:Number(page.value),original_file:f.id});card.append(page,preview);}$('files').append(card);}}
function closePreview(){previewRequest++;$('source-viewer').hidden=true;$('source-image').removeAttribute('src');$('source-caption').textContent='';}
async function showPreview(r){const session=current,request=++previewRequest;$('source-viewer').hidden=false;$('source-viewer').closest('details').open=true;$('source-image').removeAttribute('src');$('source-caption').textContent='Загружаем страницу…';try{const response=await api(r.original_file?`/api/sessions/${session}/files/${r.original_file}/preview?page=${r.page}`:`/api/sessions/${session}/evidence/${r.id}/preview`);if(response.headers.get('content-type')!=='image/png')throw new Error('Неверный формат просмотра');const bytes=await response.arrayBuffer();if(bytes.byteLength>10*1024*1024)throw new Error('Изображение превышает лимит');const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Не удалось прочитать страницу'));reader.readAsDataURL(new Blob([new Uint8Array(bytes)],{type:'image/png'}));});if(request!==previewRequest||session!==current)return;$('source-image').src=url;$('source-caption').textContent=r.name+' · стр. '+r.page+' · '+(r.original_file?'Оригинал для визуальной сверки':r.provenance?.status==='UNIQUE'?'Область цитаты':'Кандидатные области, расположение не подтверждено')+'. Подсветка не подтверждает инженерный вывод.';}catch(e){if(request===previewRequest&&session===current){closePreview();error(e);}}}
$('close-preview').onclick=closePreview;
const REVIEW_LABELS={SOURCE_CONFIRMED:'Цитата и место сверены (запись пользователя)',REJECTED:'Не соответствует источнику',NEEDS_DATA:'Нужны данные',NOT_REVIEWED:'Не проверено'};
function closeReview(){reviewTarget=null;$('review-panel').hidden=true;$('review-caption').textContent='';$('review-note').value='';$('review-decision').value='NEEDS_DATA';$('review-actor').value='Локальный пользователь';controls();}
function openReview(r){if(pending||uploading)return;const same=reviewTarget?.id===r.id&&reviewTarget?.session===current;reviewTarget={id:r.id,session:current,revision:r.review_revision||0};if(!same){$('review-note').value='';$('review-decision').value='NEEDS_DATA';$('review-actor').value='Локальный пользователь';}$('review-panel').hidden=false;$('review-caption').textContent=r.name+(r.page?' · стр. '+r.page:'')+' · '+r.quote+' · SHA256 '+r.source_sha256;const pdf=r.name.toLowerCase().endsWith('.pdf');$('review-decision').querySelector('[value="SOURCE_CONFIRMED"]').disabled=r.source_match!=='MATCH'||r.source_confirmable===false||(pdf&&r.provenance?.status!=='UNIQUE');controls();}
$('close-review').onclick=closeReview;
$('review-form').onsubmit=async event=>{event.preventDefault();if(!reviewTarget||pending||uploading)return;const target={...reviewTarget};pending=true;controls();error(null);try{await api(`/api/sessions/${target.session}/evidence/${target.id}/reviews`,{method:'POST',body:{expected_revision:target.revision,decision:$('review-decision').value,note:$('review-note').value,actor:$('review-actor').value}});closeReview();await refresh();}catch(e){error(e);await refresh();}finally{pending=false;controls();}};
function renderEvidence(snap){const select=$('evidence-file'),choice=select.value;select.replaceChildren();for(const f of snap.files){const option=node('option',f.name);option.value=f.id;select.append(option);}if(snap.files.some(f=>f.id===choice))select.value=choice;$('evidence-list').replaceChildren();for(const r of snap.evidence||[]){const card=node('article',undefined,'evidence-card');card.append(node('strong','UNVERIFIED · '+(r.source_match==='MATCH'?'цитата совпала':'цитата не проверена')),node('p',r.statement),node('blockquote',r.quote),node('small',r.name+(r.page?' · стр. '+r.page:'')+' · SHA256 '+r.source_sha256),node('p',r.verification_note));if(r.locator)card.append(node('p',sourceLocation(r),'logical-location'));card.append(node('small','Тип данных: '+r.data_class+' · заявлен пользователем, не проверен'));for(const limit of r.source_binding?.limitations||[])card.append(node('small',limit));if(r.provenance){const p=r.provenance;const labels={UNIQUE:'Одно место',AMBIGUOUS:'Неоднозначное расположение',NOT_LOCATED:'Координаты не найдены',NOT_APPLICABLE:'PDF-координаты неприменимы'};card.append(node('p',labels[p.status]||p.status,'provenance-status'));for(const box of p.regions.slice(0,10))card.append(node('small',`Область: ${box.left.toFixed(2)}, ${box.top.toFixed(2)} → ${box.right.toFixed(2)}, ${box.bottom.toFixed(2)} pt`));if(p.coordinate_system)card.append(node('small','Координаты от верхнего левого угла страницы без поворота; поворот '+p.page_rotation+'°'));if(p.regions_total>10)card.append(node('small','Показаны первые 10 областей.'));card.append(node('p',r.document_validation?.status==='VALIDATED'?'Привязка цитаты проверена; содержание не подтверждено.':'Привязка к единственной области не подтверждена.'));}if(r.page&&/\.(pdf|png|jpg|jpeg)$/i.test(r.name)){const button=node('button','Посмотреть страницу','preview-button text-button');button.onclick=()=>showPreview(r.name.toLowerCase().endsWith('.pdf')?r:{...r,original_file:r.file_id});card.append(button);}const reviewButton=node('button','Проверить источник','review-button text-button');reviewButton.onclick=()=>openReview(r);card.append(reviewButton);if(r.reviews?.length){const history=node('details',undefined,'review-history');history.append(node('summary',`История решений · ${r.reviews.length}`));for(const e of r.reviews)history.append(node('p',`#${e.revision} · ${REVIEW_LABELS[e.decision]||e.decision} · ${e.actor} · ${new Date(e.created*1000).toLocaleString()}`),node('p',e.note));history.append(node('small','Подпись указана пользователем; инженерное принятие отсутствует.'));card.append(history);}$('evidence-list').append(card);}}
function renderEngineeringReview(box,review){if(!review)return;const section=node('details',undefined,'engineering-review');section.append(node('summary','Сверка требований и ролей · '+review.status),node('small','Воспроизводимый снимок: '+review.snapshot_sha256));for(const requirement of review.requirements){const row=node('article',undefined,'engineering-requirement');row.append(node('strong',requirement.text+' · '+requirement.status),node('small',requirement.reasons.join(', ')));for(const observation of requirement.observations){row.append(node('p',observation.agent+' · '+observation.relation+' · '+observation.text));for(const source of observation.sources)row.append(node('small','Кандидат '+source.candidate_id+' · SHA256 '+source.source_sha256+' · проверка '+source.review_event_id+' · автор '+(source.reviewer||'не указан')));}section.append(row);}for(const reason of review.reasons)section.append(node('small',reason));section.append(node('small','Связь заявлена моделью; тип данных, конструкция и инженерный вывод требуют проверки. FINAL AUDIT NOT_RUN.'));box.append(section);}
