const caseRoleLabels={TOR:'ТЗ',REPORT:'Отчёт',CALCULATION_REPORT:'Расчётный отчёт',MODEL:'Модель',GEODESY:'Геодезия',GRAPHICS:'Чертежи',PHOTO:'Фото',OTHER:'Другое'};
let caseRoleKey='',caseRoleJobs=[],caseRoleFiles=[];
function resetCaseRoles(){caseRoleKey='';caseRoleJobs=[];caseRoleFiles=[];caseRoles.replaceChildren();realCaseJob.value='';realCaseManifest.value='';}
function renderCaseRoles(){const job=caseRoleJobs.find(j=>j.id===realCaseJob.value);const files=caseRoleFiles.filter(f=>job?.file_ids.includes(f.id));const key=JSON.stringify([job?.id,files.map(f=>[f.id,f.name])]);if(key===caseRoleKey)return;caseRoleKey=key;caseRoles.replaceChildren(node('legend','Назначьте роли оригиналам из выбранного анализа'));
 if(!files.length){caseRoles.append(node('p','Выберите анализ с прикреплёнными файлами.'));return;}
 for(const [role,label] of Object.entries(caseRoleLabels)){const group=node('details');group.append(node('summary',label));for(const f of files){const box=node('label',f.name);const check=node('input');check.type='checkbox';check.dataset.caseRole=role;check.value=f.id;box.prepend(check);group.append(box);}caseRoles.append(group);}}
