function renderFinalAudit(report,realCase){
 finalAuditRevision=report.revision||0;window.__engineerCurrentCase=(realCase.cases||[]).find(x=>x.current)||null;
 finalAuditStatus.textContent=report.audits?.length?`Версий: ${report.revision} · FINAL AUDIT ${report.status} · ${report.current_fresh?'актуален':'устарел'}`:'FINAL AUDIT ещё не выполнялся.';
 finalAuditResults.replaceChildren();
 for(const audit of (report.audits||[]).slice(-5).reverse()){const card=node('article',undefined,'final-audit-result');card.append(node('strong',`FINAL AUDIT #${audit.revision} · ${audit.effective_decision||audit.decision}`),node('p','Audit SHA256: '+audit.audit_sha256),node('p','Case SHA256: '+audit.case_sha256),node('small',(audit.current?'текущий':'исторический')+' · '+(audit.fresh?'актуален':'не актуален')));
  for(const check of audit.checks||[])card.append(node('p',check.dimension+' · '+check.status),node('small',(check.reasons||[]).join(', ')));
  if(audit.blocker_codes?.length)card.append(node('small','BLOCK: '+audit.blocker_codes.join(', ')));
  if(audit.stale_reasons?.length)card.append(node('small','Audit stale: '+audit.stale_reasons.join(', ')));
  card.append(node('strong',audit.effective_acceptance_granted?'ACCEPTED':'NOT ACCEPTED'),node('small','acceptance_granted='+(audit.effective_acceptance_granted?'true':'false')+' · FINAL AUDIT COMPLETED'));finalAuditResults.append(card);}
}
for(const form of [normativeForm,calculationForm,advancedDomainForm]){form.addEventListener('input',()=>{if(!domainDraftRevisions.has(form))domainDraftRevisions.set(form,domainRevision);});const currentButton=node('button','Использовать текущую версию после сверки','domain-use-current-revision');currentButton.type='button';currentButton.onclick=()=>{domainDraftRevisions.set(form,domainRevision);error(null);};form.append(currentButton);}
let domainCandidates=[];
async function submitDomain(form,packet){if(!current||pending||uploading)return;const session=current;pending=true;controls();normButton.disabled=true;calcButton.disabled=true;advancedButton.disabled=true;error(null);try{await api(`/api/sessions/${session}/domain-packets`,{method:'POST',body:{expected_revision:domainDraftRevisions.get(form)??domainRevision,packet}});form.reset();quantityToggle.onchange();domainDraftRevisions.delete(form);await refresh();}catch(e){error(e);}finally{pending=false;normButton.disabled=false;calcButton.disabled=false;advancedButton.disabled=false;controls();}}
normativeForm.onsubmit=event=>{event.preventDefault();const packet={kind:'NORMATIVE',chain:Object.fromEntries(Object.entries(chainInputs).map(([k,v])=>[k,v.value])),norm_ids:[normSource.value],actual_ids:[actualSource.value],quantities:null};if(quantityToggle.checked){const quantities={operator:operator.value};for(const kind of ['actual','limit'])quantities[kind]={candidate_id:kind==='actual'?actualSource.value:normSource.value,value:quantityInputs[kind+'-value'].value,unit:quantityInputs[kind+'-unit'].value,fragment:quantityInputs[kind+'-fragment'].value};packet.quantities=quantities;}submitDomain(normativeForm,packet);};
calculationForm.onsubmit=event=>{event.preventDefault();const bindings=[];for(const [role,select] of Object.entries(calcSelects)){const candidate=domainCandidates.find(c=>c.id===select.value);if(candidate)bindings.push({role,file_id:candidate.file_id,candidate_ids:[candidate.id]});}if(!bindings.length){error('Выберите хотя бы один расчётный источник');return;}submitDomain(calculationForm,{kind:'CALCULATION',bindings});};
advancedDomainForm.onsubmit=event=>{event.preventDefault();let packet;try{packet=JSON.parse(advancedDomainJson.value);}catch(_){error('Расширенный пакет должен быть корректным JSON');return;}if(!packet||typeof packet!=='object'||Array.isArray(packet)){error('Расширенный пакет должен быть JSON-объектом');return;}submitDomain(advancedDomainForm,packet);};
function resetDomains(){domainDraftRevisions.clear();domainRevision=0;domainOptionsKey='';normativeForm.reset();calculationForm.reset();advancedDomainForm.reset();quantityToggle.onchange();}
function renderDomains(report,candidates){domainRevision=report.revision;domainCandidates=candidates;domainStatus.textContent='Версий: '+report.revision+' · '+report.status+' · инженерное принятие отсутствует';const key=JSON.stringify(candidates.map(c=>[c.id,c.name,c.quote,c.review_revision]));if(key!==domainOptionsKey){domainOptionsKey=key;for(const select of domainPanel.querySelectorAll('.domain-source-select')){const old=select.value;select.replaceChildren();const blank=node('option','Источник не выбран');blank.value='';select.append(blank);for(const candidate of candidates){const o=node('option',candidate.name+' · '+candidate.quote.slice(0,100));o.value=candidate.id;select.append(o);}select.value=old;}}
 domainResults.replaceChildren();for(const packet of report.packets){const card=node('article',undefined,'domain-packet-result');card.append(node('strong',packet.kind+' · версия '+packet.revision+' · '+packet.status),node('p',packet.traceability),node('p','Пункт 6: '+(packet.point6_readiness||'BLOCKED_PREREQUISITES')),node('small',packet.reasons.join(', ')));
 const checks=[['Источник нормы',packet.authority_source],['Применимость нормы',packet.authority_review],['Классы данных',packet.data_class_review],['Семантика расчёта',packet.semantic_review],['Exchange',packet.exchange_review],['Solver receipt',packet.solver_review],['Execution identity',packet.execution_review],['Результаты',packet.result_review],['Фактическая конструкция',packet.structure_review]];for(const [label,value] of checks)if(value)card.append(node('small',label+': '+value.status));if(packet.kind==='NORMATIVE')for(const [key,label] of Object.entries(chainLabels))card.append(node('p',label+': '+packet.packet.chain[key]));if(packet.arithmetic){const a=packet.arithmetic;card.append(node('p','Арифметика: '+a.actual_si+' '+a.operator+' '+a.limit_si+' · '+(a.satisfied?'условие выполнено':'условие не выполнено')),node('small','Сравнение введённых значений. Истинность факта и применимость нормы не подтверждены.'));}if(packet.intake)card.append(node('p','Роли: '+packet.packet.bindings.map(b=>b.role).join(', ')),node('small','Отсутствуют: '+packet.intake.missing_roles.join(', ')));for(const source of packet.sources)card.append(node('blockquote',source.quote),node('small',source.candidate_id+' · '+source.status+' · SHA256 '+source.source_sha256));domainResults.append(card);}}

// Route links use the existing forms; no second project store or acceptance authority.
function goStage(stage){const targets={project:document.querySelector('.conversation'),documents:document.querySelector('.drive-panel'),review:document.querySelector('.evidence-panel'),calculations:domainPanel,conclusion:realCasePanel,history:$('history-panel')};const target=targets[stage];if(!target)return;if(target.tagName==='DETAILS')target.open=true;if(stage==='documents')document.querySelector('.tz-panel').open=true;if(stage==='conclusion')finalAuditPanel.open=true;if(stage==='history'&&!historyLoaded)loadHistory();target.scrollIntoView?.({behavior:'smooth',block:'start'});const focus=target.querySelector('textarea,input:not([type=hidden]),select,button');focus?.focus({preventScroll:true});}
$('project-route').onclick=event=>{const button=event.target.closest('button[data-stage]');if(button)goStage(button.dataset.stage);};
function renderRoute(snap,tz,realCase,audit){let stage='documents',next='Прикрепить документ и заполнить требования ТЗ',state='Подготовка проекта';const active=snap.jobs.filter(j=>['QUEUED','RUNNING'].includes(j.state));if(active.length){state='Выполняются задачи: '+active.length;stage='history';next='Посмотреть ход задач и сохранённые результаты';}else if(snap.files.length&&tz.requirements?.length){stage='review';state='Источники и требования требуют проверки';next='Сверить цитаты и привязать основания к требованиям ТЗ';if(snap.jobs.some(j=>j.mode==='CORE_RUN'&&j.result)){stage='conclusion';state='Профильные черновики сохранены; инженерное принятие отсутствует';next='Назначить роли файлов и собрать снимок проекта';}}
 const currentAudit=(audit.audits||[]).find(a=>a.current),currentCase=(realCase.cases||[]).find(c=>c.current);if(currentAudit){state='Финальная проверка: '+(currentAudit.effective_decision||currentAudit.decision)+(currentAudit.fresh?'':' · результат устарел');stage='conclusion';next=!currentAudit.fresh?'Обновить снимок проекта и повторить финальную проверку':currentAudit.effective_acceptance_granted?'Посмотреть решение финальной проверки':'Посмотреть причины блокировки и необходимые данные';}else if(currentCase){stage='conclusion';state=currentCase.fresh?'Снимок проекта сохранён; финальная проверка ещё не выполнена':'Снимок проекта устарел';next=currentCase.fresh?'Открыть итог и выполнить финальную проверку':'Обновить снимок проекта перед финальной проверкой';}
 $('project-state').textContent=state;$('project-next').textContent='Следующий шаг: '+next;$('project-next').onclick=()=>goStage(stage);
}

// Archive pages are independent of the live conversation window and use stable cursors.
const historyPanel=node('details');historyPanel.id='history-panel';historyPanel.append(node('summary','Полная история проекта'));
const historyKind=node('select');historyKind.id='history-kind';historyKind.setAttribute('aria-label','Вид истории');for(const [value,label] of [['messages','Сообщения'],['jobs','Задачи и результаты']]){const option=node('option',label);option.value=value;historyKind.append(option);}
const historyReload=node('button','Обновить архив');historyReload.type='button';const historyMore=node('button','Ещё 50 записей');historyMore.type='button';historyMore.id='history-more';historyMore.hidden=true;
const historyRecords=node('div');historyRecords.id='history-records';const historyStatus=node('p');historyStatus.id='history-status';
historyPanel.append(node('p','От новых записей к старым. Архив не меняет инженерные решения.'),historyKind,historyReload,historyRecords,historyStatus,historyMore);$('jobs').after(historyPanel);
let historyCursor=null,historyLoaded=false,historyGeneration=0,historyBusy=false;
function resetHistory(){historyGeneration++;historyBusy=false;historyLoaded=false;historyCursor=null;historyRecords.replaceChildren();historyStatus.textContent='';historyMore.hidden=true;historyPanel.open=false;historyKind.value='messages';historyKind.disabled=false;historyReload.disabled=false;}
async function loadHistory(more=false){if(!current||historyBusy)return;const session=current,generation=++historyGeneration,kind=historyKind.value;historyBusy=true;historyKind.disabled=true;historyReload.disabled=true;historyMore.disabled=true;historyStatus.textContent='Загружаем архив…';try{const page=await api(`/api/sessions/${session}/history?kind=${kind}&limit=50`+(more&&historyCursor?'&before='+historyCursor:''));if(session!==current||generation!==historyGeneration)return;if(!more)historyRecords.replaceChildren();if(kind==='messages'){for(const message of page.records){const card=node('article',undefined,'history-record message');card.append(node('strong',message.role==='user'?'ВЫ':'ENGINEER OS'),node('small',new Date(message.created*1000).toLocaleString()),node('p',message.content,'message-body'));if(message.role==='assistant')card.append(node('small','Исторический ответ · требуется проверка'));historyRecords.append(card);}}else{const box=node('div',undefined,'history-record');renderJobs(page.records,box,200);historyRecords.append(box);}historyCursor=page.next_before;historyLoaded=true;historyMore.hidden=!page.has_more;historyStatus.textContent=page.records.length?(page.has_more?'Есть более ранние записи.':'Начало истории достигнуто.'):'В этом проекте записей нет.';}catch(e){if(session===current&&generation===historyGeneration){error(e);historyStatus.textContent='Архив не загрузился. Повторите обновление.';}}finally{if(session===current&&generation===historyGeneration){historyBusy=false;historyKind.disabled=false;historyReload.disabled=false;historyMore.disabled=false;}}}
historyKind.onchange=()=>{historyLoaded=false;loadHistory();};historyReload.onclick=()=>loadHistory();historyMore.onclick=()=>loadHistory(true);

